//! Parity of the Rust presenter with the TS presenter (`quarto.jupyter.toMarkdown`, which
//! the Julia engine uses today) over stored QNR-shaped notebooks.
//!
//! `tests/fixtures/julia-presenter-parity/<case>.ipynb` are the inputs and
//! `<case>.ts.md` the TS presenter's markdown for them, generated by
//! `scripts/exr-julia-parity/generate-ts-goldens.sh` (`--check` is the freshness check).
//! This test presents each notebook through the engine stage's stored-notebook replay
//! (the Rust presenter) and compares structure, not bytes: block kinds, div and code
//! block classes, and figure file names. Every difference is listed; `ACCEPTED` names the
//! ones EXR-8 decided to keep, each with its classification, and anything else fails.
//! Set `JULIA_PARITY_REPORT=1` to print every divergence as it is found.

#![cfg(not(target_arch = "wasm32"))]

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};

use quarto_pandoc_types::Block;
use tempfile::TempDir;

use quarto_core::stage::stages::ENGINE_CAPTURE_KIND;

use crate::engine_stage_driver::{AuxRecorder, run_engine_stage};

const CASES: &[&str] = &[
    "cap-location",
    "cell-classes",
    "code-overflow",
    "echo-false",
    "error-allowed",
    "fig-column",
    "hidden-then-plot",
    "html-table",
    "markdown-latex",
    "png-and-svg",
    "stderr-and-multiple",
    "value-and-stdout",
];

/// Divergences EXR-8 accepted: `(case, divergence prefix, reason)`.
const ACCEPTED: &[(&str, &str, &str)] = &[
    // KNR-3 slice 7, D5: the Rust presenter writes `caption-<cap-location>`; TS (and Quarto 1)
    // write `caption-<fig-cap-location>`, which is `caption-undefined` when only `cap-location`
    // is set (quarto-dev/quarto-cli#15281; the TS copy is bd-3uj42ytc). Classification: accept.
    (
        "cap-location",
        "div-classes at blocks[0]",
        "cap-location writes its own value, not fig-cap-location's",
    ),
    // The Rust presenter's figure div carries only `cell-output-display`, matching
    // q2-knitr (`presenter/cell.rs`, "Figure divs carry ONLY `cell-output-display`").
    // TS adds `cell-output`. Classification: accept.
    (
        "png-and-svg",
        "div-classes at blocks[0][1]",
        "figure div classes",
    ),
    (
        "png-and-svg",
        "div-classes at blocks[1][1]",
        "figure div classes",
    ),
    (
        "hidden-then-plot",
        "div-classes at blocks[0][1]",
        "figure div classes",
    ),
    // The KNR-3 slice 7 fixtures plot a figure too; their option (classes, code-overflow,
    // fig-column) matches TS, and only this known figure div difference remains.
    (
        "cell-classes",
        "div-classes at blocks[0][1]",
        "figure div classes",
    ),
    (
        "code-overflow",
        "div-classes at blocks[0][1]",
        "figure div classes",
    ),
    (
        "fig-column",
        "div-classes at blocks[0][1]",
        "figure div classes",
    ),
];

/// Divergences classified `fix-rust` and not yet fixed: `(case, divergence prefix, what)`.
/// B4 may flip only when this is empty (`no_pending_fix_rust_divergences`). The
/// `text/markdown` and `text/latex` handlers closed the only entries it ever held.
const PENDING_FIX_RUST: &[(&str, &str, &str)] = &[];

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/julia-presenter-parity")
}

/// The Rust presenter's markdown for `case`, through the stored-notebook replay route.
fn rust_markdown(case: &str) -> String {
    let dir = TempDir::new().unwrap();
    // The name the generator renders under, so figure directories compare equal.
    let input = dir.path().join("notebook.ipynb");
    std::fs::copy(root().join(format!("{case}.ipynb")), &input).unwrap();
    let observer = AuxRecorder::arc(false);
    run_engine_stage(&input, observer.clone(), None).expect("the engine stage runs");
    let captures = observer.events_of(ENGINE_CAPTURE_KIND);
    assert_eq!(captures.len(), 1, "{case}: one engine capture");
    captures[0].1["result"]["markdown"]
        .as_str()
        .expect("the capture carries markdown")
        .to_string()
}

fn parse(markdown: &str) -> Vec<Block> {
    pampa::readers::qmd::read(
        markdown.as_bytes(),
        false,
        "parity.md",
        &mut std::io::sink(),
        false,
        None,
    )
    .expect("parse presenter markdown")
    .0
    .blocks
}

/// Classes that do not describe the presentation: the language of a code block.
fn comparable_classes(attr: &quarto_pandoc_types::attr::Attr, lang: &str) -> Vec<String> {
    let mut classes: Vec<String> = attr.1.iter().filter(|c| *c != lang).cloned().collect();
    classes.sort();
    classes
}

fn kind(b: &Block) -> &'static str {
    match b {
        Block::Paragraph(_) => "Paragraph",
        Block::Plain(_) => "Plain",
        Block::CodeBlock(_) => "CodeBlock",
        Block::Div(_) => "Div",
        Block::RawBlock(_) => "RawBlock",
        Block::Header(_) => "Header",
        _ => "Other",
    }
}

fn compare_blocks(rust: &[Block], ts: &[Block], path: &str, out: &mut Vec<String>) {
    if rust.len() != ts.len() {
        out.push(format!(
            "block-count at {path}: rust {:?} vs ts {:?}",
            rust.iter().map(kind).collect::<Vec<_>>(),
            ts.iter().map(kind).collect::<Vec<_>>()
        ));
        return;
    }
    for (i, (r, t)) in rust.iter().zip(ts).enumerate() {
        let p = format!("{path}[{i}]");
        match (r, t) {
            (Block::Div(r), Block::Div(t)) => {
                let (rc, tc) = (
                    comparable_classes(&r.attr, ""),
                    comparable_classes(&t.attr, ""),
                );
                if rc != tc {
                    out.push(format!("div-classes at {p}: rust {rc:?} vs ts {tc:?}"));
                }
                compare_blocks(&r.content, &t.content, &p, out);
            }
            (Block::CodeBlock(r), Block::CodeBlock(t)) => {
                // The language class is the first class on both sides.
                let lang =
                    |a: &quarto_pandoc_types::attr::Attr| a.1.first().cloned().unwrap_or_default();
                let (rl, tl) = (lang(&r.attr), lang(&t.attr));
                if rl != tl {
                    out.push(format!("code-language at {p}: rust {rl:?} vs ts {tl:?}"));
                }
                let (rc, tc) = (
                    comparable_classes(&r.attr, &rl),
                    comparable_classes(&t.attr, &tl),
                );
                if rc != tc {
                    out.push(format!("code-classes at {p}: rust {rc:?} vs ts {tc:?}"));
                }
            }
            (r, t) if std::mem::discriminant(r) != std::mem::discriminant(t) => {
                out.push(format!(
                    "block-kind at {p}: rust {} vs ts {}",
                    kind(r),
                    kind(t)
                ));
            }
            _ => {}
        }
    }
}

/// The figure file names a document links, in order.
fn figure_names(markdown: &str) -> Vec<String> {
    regex::Regex::new(r"\]\(([^)\s]*_files/[^)\s]*)\)")
        .unwrap()
        .captures_iter(markdown)
        .map(|c| c[1].to_string())
        .collect()
}

/// TS figure names with the cell number lowered by one. TS names a figure
/// `cell-<index + 1>-output-<n>` over `nb.cells`; rendering a `.ipynb` as a document puts
/// a front matter cell first, which a QNR notebook handed to the engine does not have, so
/// the Rust numbers are the ones the Julia engine would produce today.
fn without_front_matter_cell(names: Vec<String>) -> Vec<String> {
    let re = regex::Regex::new(r"/cell-(\d+)-output-").unwrap();
    names
        .into_iter()
        .map(|n| {
            re.replace(&n, |c: &regex::Captures| {
                format!("/cell-{}-output-", c[1].parse::<usize>().unwrap() - 1)
            })
            .into_owned()
        })
        .collect()
}

fn divergences(case: &str) -> Vec<String> {
    let rust = rust_markdown(case);
    let ts = std::fs::read_to_string(root().join(format!("{case}.ts.md"))).unwrap_or_else(|e| {
        panic!("{case}.ts.md: {e}; run scripts/exr-julia-parity/generate-ts-goldens.sh")
    });
    let mut out = Vec::new();
    compare_blocks(&parse(&rust), &parse(&ts), "blocks", &mut out);
    let (rf, tf) = (
        figure_names(&rust),
        without_front_matter_cell(figure_names(&ts)),
    );
    if rf != tf {
        out.push(format!("figure-names: rust {rf:?} vs ts {tf:?}"));
    }
    out
}

#[test]
fn rust_presenter_matches_ts_presenter_on_julia_notebooks() {
    let report = std::env::var_os("JULIA_PARITY_REPORT").is_some();
    let mut unaccepted = Vec::new();
    for case in CASES {
        for d in divergences(case) {
            if report {
                eprintln!("[{case}] {d}");
            }
            let known = |list: &[(&str, &str, &str)]| {
                list.iter()
                    .any(|(c, prefix, _)| c == case && d.starts_with(prefix))
            };
            if !known(ACCEPTED) && !known(PENDING_FIX_RUST) {
                unaccepted.push(format!("[{case}] {d}"));
            }
        }
    }
    assert!(
        unaccepted.is_empty(),
        "{} unaccepted divergence(s):\n{}",
        unaccepted.len(),
        unaccepted.join("\n")
    );
}

/// The B4 gate: nothing classified `fix-rust` is still open.
#[test]
fn no_pending_fix_rust_divergences() {
    assert!(
        PENDING_FIX_RUST.is_empty(),
        "{} fix-rust divergence(s) pending: {PENDING_FIX_RUST:?}",
        PENDING_FIX_RUST.len()
    );
}

#[test]
fn every_parity_fixture_is_consumed() {
    let mut expected: BTreeSet<String> = BTreeSet::new();
    for case in CASES {
        expected.insert(format!("{case}.ipynb"));
        expected.insert(format!("{case}.ts.md"));
    }
    let present: BTreeSet<String> = std::fs::read_dir(root())
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    assert_eq!(present, expected);
}
